<?php require_once dirname(__DIR__).'/includes/functions.php';require_role('counselor');$q=trim($_GET['q']??'');$like='%'.$q.'%';$stmt=$con->prepare("SELECT u.id,u.name,u.email,u.education_level,u.created_at,COUNT(DISTINCT CASE WHEN p.status='completed' THEN p.id END) simulations,COUNT(DISTINCT CASE WHEN a.passed=1 THEN a.id END) quizzes FROM users u LEFT JOIN user_simulation_progress p ON p.user_id=u.id LEFT JOIN quiz_attempts a ON a.user_id=u.id WHERE u.role='student' AND u.deleted_at IS NULL AND (u.name LIKE ? OR u.email LIKE ?) GROUP BY u.id ORDER BY u.name");$stmt->bind_param('ss',$like,$like);$stmt->execute();$students=$stmt->get_result();$pageTitle='Counselor view';require dirname(__DIR__).'/includes/header.php';?><div class="container py-5"><h1>Counselor view</h1><p class="text-muted">Read-only student progress oversight.</p><form class="card p-3 mb-4"><div class="input-group"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search students"><button class="btn btn-primary">Search</button></div></form><div class="card table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Student</th><th>Education</th><th>Simulations</th><th>Quiz passes</th><th></th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><strong><?=e($s['name'])?></strong><div class="small text-muted"><?=e($s['email'])?></div></td><td><?=e($s['education_level'])?></td><td><?=$s['simulations']?></td><td><?=$s['quizzes']?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=url('counselor/student_view.php?id='.$s['id'])?>">View profile</a></td></tr><?php endforeach?></tbody></table></div></div><?php require dirname(__DIR__).'/includes/footer.php';?>
